package com.notebox.platform.service;

import com.notebox.platform.dto.ApiResponse;
import com.notebox.platform.dto.LoginRequest;
import com.notebox.platform.dto.LoginResponse;
import com.notebox.platform.entity.User;
import com.notebox.platform.mapper.UserMapper;
import com.notebox.platform.util.JwtUtil;
import java.util.Objects;
import org.springframework.stereotype.Service;

@Service
public class AuthService {
    private final UserMapper userMapper;
    private final JwtUtil jwtUtil;

    public AuthService(UserMapper userMapper, JwtUtil jwtUtil) {
        this.userMapper = userMapper;
        this.jwtUtil = jwtUtil;
    }

    public ApiResponse<LoginResponse> login(LoginRequest request) {
        User user = request == null ? null : userMapper.findByUsername(request.getUsername());
        if (user == null || !Objects.equals(user.getPassword(), request.getPassword())) {
            return ApiResponse.error(401, "用户名或密码错误");
        }
        LoginResponse response = new LoginResponse(
                jwtUtil.generateToken(user), user.getUsername(), user.getRole());
        return ApiResponse.success("登录成功", response);
    }
}

package com.notebox.platform.service;

import com.notebox.platform.dto.ApiResponse;
import com.notebox.platform.dto.NoteCreateRequest;
import com.notebox.platform.dto.NoteReadRequest;
import com.notebox.platform.dto.NoteUpdateRequest;
import com.notebox.platform.entity.Note;
import com.notebox.platform.mapper.NoteMapper;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

@Service
public class NoteService {
    private final NoteMapper noteMapper;
    private final Path workspaceRoot;

    public NoteService(NoteMapper noteMapper,
                       @Value("${notebox.workspace.root}") String workspaceRoot) {
        this.noteMapper = noteMapper;
        this.workspaceRoot = Path.of(workspaceRoot).toAbsolutePath().normalize();
    }

    public ApiResponse<?> create(Long workspaceId, NoteCreateRequest request) {
        String requestedPath = request == null ? null : request.getPath();
        if (isEmptyPath(requestedPath)) {
            return ApiResponse.error(400, "路径不能为空");
        }
        try {
            Path file = resolvePath(workspaceId, requestedPath);
            Path parent = file.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            byte[] bytes = bytes(request.getContent());
            Files.write(file, bytes);

            LocalDateTime now = LocalDateTime.now();
            Note note = new Note(null, workspaceId, request.getTitle(), requestedPath,
                    (long) bytes.length, now, now);
            noteMapper.insert(note);

            Map<String, Object> data = new LinkedHashMap<>();
            data.put("id", note.getId());
            data.put("workspaceId", note.getWorkspaceId());
            data.put("title", note.getTitle());
            data.put("path", note.getPath());
            data.put("fileSize", note.getFileSize());
            data.put("createdAt", note.getCreatedAt().toString());
            return ApiResponse.success("创建成功", data);
        } catch (IOException e) {
            return ApiResponse.error(500, "文件写入失败: " + detail(e));
        }
    }

    public ApiResponse<?> read(Long workspaceId, NoteReadRequest request) {
        String requestedPath = request == null ? null : request.getPath();
        if (isEmptyPath(requestedPath)) {
            return ApiResponse.error(400, "路径不能为空");
        }
        try {
            Path file = resolvePath(workspaceId, requestedPath);
            if (!Files.exists(file)) {
                return ApiResponse.error(404, "文件不存在");
            }
            String content = Files.readString(file, StandardCharsets.UTF_8);
            Map<String, Object> data = new LinkedHashMap<>();
            data.put("path", requestedPath);
            data.put("content", content);
            data.put("fileSize", Files.size(file));
            return ApiResponse.success(data);
        } catch (IOException e) {
            return ApiResponse.error(500, "文件读取失败: " + detail(e));
        }
    }

    public ApiResponse<?> update(Long workspaceId, NoteUpdateRequest request) {
        String requestedPath = request == null ? null : request.getPath();
        if (isEmptyPath(requestedPath)) {
            return ApiResponse.error(400, "路径不能为空");
        }
        try {
            Path file = resolvePath(workspaceId, requestedPath);
            if (!Files.exists(file)) {
                return ApiResponse.error(404, "文件不存在");
            }
            byte[] bytes = bytes(request.getContent());
            Files.write(file, bytes);
            LocalDateTime updatedAt = LocalDateTime.now();
            Note note = noteMapper.findByWorkspaceIdAndPath(workspaceId, requestedPath);
            if (note != null) {
                noteMapper.updateFileInfo(note.getId(), (long) bytes.length, updatedAt);
            }
            Map<String, Object> data = new LinkedHashMap<>();
            data.put("path", requestedPath);
            data.put("fileSize", (long) bytes.length);
            data.put("updatedAt", updatedAt.toString());
            return ApiResponse.success("更新成功", data);
        } catch (IOException e) {
            return ApiResponse.error(500, "文件写入失败: " + detail(e));
        }
    }

    public ApiResponse<?> delete(Long workspaceId, NoteReadRequest request) {
        String requestedPath = request == null ? null : request.getPath();
        if (isEmptyPath(requestedPath)) {
            return ApiResponse.error(400, "路径不能为空");
        }
        try {
            Path file = resolvePath(workspaceId, requestedPath);
            if (!Files.exists(file)) {
                return ApiResponse.error(404, "文件不存在");
            }
            Files.delete(file);
            Note note = noteMapper.findByWorkspaceIdAndPath(workspaceId, requestedPath);
            if (note != null) {
                noteMapper.deleteById(note.getId());
            }
            return ApiResponse.success("删除成功", null);
        } catch (IOException e) {
            return ApiResponse.error(500, "文件删除失败: " + detail(e));
        }
    }

    public ApiResponse<List<Note>> list(Long workspaceId) {
        return ApiResponse.success(noteMapper.findByWorkspaceId(workspaceId));
    }

    private boolean isEmptyPath(String path) {
        return path == null || path.trim().isEmpty();
    }

    private byte[] bytes(String content) {
        return (content == null ? "" : content).getBytes(StandardCharsets.UTF_8);
    }

    private Path resolvePath(Long workspaceId, String requestedPath) throws IOException {
        try {
            Path workspace = workspaceRoot.resolve(workspaceId.toString()).normalize();
            Path resolved = workspace.resolve(requestedPath).normalize();
            if (!resolved.startsWith(workspace)) {
                throw new IOException("路径超出工作区");
            }
            return resolved;
        } catch (InvalidPathException e) {
            throw new IOException(e.getMessage(), e);
        }
    }

    private String detail(IOException exception) {
        return exception.getMessage() == null ? exception.getClass().getSimpleName() : exception.getMessage();
    }
}

package com.notebox.platform.service;

import com.notebox.platform.dto.ApiResponse;
import com.notebox.platform.dto.WorkspaceRequest;
import com.notebox.platform.entity.Workspace;
import com.notebox.platform.mapper.WorkspaceMapper;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

@Service
public class WorkspaceService {
    private final WorkspaceMapper workspaceMapper;
    private final Path workspaceRoot;

    public WorkspaceService(WorkspaceMapper workspaceMapper,
                            @Value("${notebox.workspace.root}") String workspaceRoot) {
        this.workspaceMapper = workspaceMapper;
        this.workspaceRoot = Path.of(workspaceRoot);
    }

    public ApiResponse<Workspace> create(WorkspaceRequest request, Long userId) {
        Workspace workspace = new Workspace(null, request.getName(), request.getDescription(),
                userId, LocalDateTime.now());
        workspaceMapper.insert(workspace);
        try {
            Files.createDirectories(workspaceRoot.resolve(workspace.getId().toString()));
        } catch (IOException ignored) {
            // Directory creation is best-effort for this endpoint by contract.
        }
        return ApiResponse.success("创建成功", workspace);
    }

    public Workspace findById(Long id) {
        return workspaceMapper.findById(id);
    }

    public ApiResponse<List<Workspace>> list(Long userId, String role) {
        List<Workspace> workspaces = "ADMIN".equals(role)
                ? workspaceMapper.findAll() : workspaceMapper.findByUserId(userId);
        return ApiResponse.success(workspaces);
    }
}

